window.VA_MAP.project = function(lon, lat){
  var w = window.VA_MAP.window, cos = Math.cos(w.latRef * Math.PI / 180), k = w.width / ((w.lon1 - w.lon0) * cos);
  return { x: (lon - w.lon0) * cos * k, y: (w.lat1 - lat) * k };
};
